// Prepare and sanitize incoming VPA list
const input = $input.first().json;
let rows = input.rows || [];

if (typeof input.csv === 'string') {
  const lines = input.csv.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length > 1) {
    const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
    rows = [];
    for (let i = 1; i < lines.length; i++) {
      const vals = lines[i].split(',').map(v => v.trim());
      const obj = {};
      headers.forEach((h, idx) => { obj[h] = vals[idx]; });
      rows.push(obj);
    }
  }
}

// Distribute time-slots evenly (33% MORNING, 33% AFTERNOON, 34% EVENING)
const slots = ['MORNING', 'AFTERNOON', 'EVENING'];
rows = rows.map((r, i) => ({
  vpa_address: (r.vpa_address || r.vpa || '').trim().toLowerCase(),
  holder_name: r.holder_name || `Account Holder ${i + 1}`,
  bank_name: r.bank_name || '',
  preferred_time_slot: r.preferred_time_slot || slots[i % 3],
  daily_tx_limit: parseInt(r.daily_tx_limit, 10) || 15,
  daily_volume_limit: parseFloat(r.daily_volume_limit) || 25000.0,
  per_tx_limit: parseFloat(r.per_tx_limit) || 5000.0
}));

return [{ json: { rows, merchantId: input.merchantId || 'mer_default', total: rows.length } }];

// Prepare notification summary
const res = $input.first().json;
const message = `🚨 *DISHA 8.2 Anti-Ban Warning*
Batch Ingestion Succeeded with Warnings:
• Total Processed: ${res.total}
• Active Added: ${res.added}
• Skipped: ${res.skipped}

⚠️ *Concentration:* ${res.bankDiversityWarning}
Recommendation: Diversify across at least 4 scheduled banks to prevent algorithmic freezing.`;
return [{ json: { status: 'WARNING', message, ...res } }];

// Prepare success summary
const res = $input.first().json;
const message = `✅ *DISHA 8.2 VPA Fleet Expanded*
Successfully integrated ${res.added} personal VPAs into rotation!
• Total Pool: ${res.total}
• Daily Safe Transactions: +${res.added * 15} txns/day
• Daily Safe Volume: +₹${((res.added * 25000) / 100000).toFixed(2)} Lakhs/day
• Bank Diversity: Balanced (<30% per bank)`;
return [{ json: { status: 'SUCCESS', message, ...res } }];
